"""Fresh engineering DEV. Synthetic known endpoints used ONLY by evaluator.
No TEST is generated by this script; no endpoint replacement or second search.
"""
from common_ap import *
from local_reference import *
cv2.setNumThreads(1)
FAMILIES=['false_tail','true_long','cross55','cross75','crossS','weak','early','preexisting','closure','negative','static_negative','hole_motion','gain_offset','reflection','low_texture','repeated','nonrigid','anchor_error']
def paint(a,p,c,w):
 m=np.zeros_like(a,np.uint8);cv2.polylines(m,[np.rint(np.asarray(p)*4).astype('int32')],False,255,max(1,round(w*4)),cv2.LINE_AA,shift=2)
 return a-m.astype(float)*(c/255)
def baseimage(rng,n,kind):
 y,x=np.mgrid[:n,:n]
 if kind==0:
  # Random Fourier surface: new generator, no historical image or old texture import.
  a=np.zeros((n,n),float)
  for _ in range(32):
   k=rng.uniform(.035,.55);theta=rng.uniform(0,2*np.pi);a+=rng.uniform(.3,1.7)*np.cos(k*(x*np.cos(theta)+y*np.sin(theta))+rng.uniform(0,2*np.pi))
  a=210+2*a
 else:
  # Stable reaction-diffusion spots from an independent two-species field.
  u=np.ones((n//2,n//2),np.float32);v=rng.uniform(0,.12,u.shape).astype('float32');u-=v
  for _ in range(38):
   uvv=u*v*v;u+=.18*cv2.Laplacian(u,cv2.CV_32F)-uvv+.045*(1-u);v+=.09*cv2.Laplacian(v,cv2.CV_32F)+uvv-.107*v
  a=211+cv2.resize((v-v.mean())/(v.std()+1e-6)*5,(n,n),interpolation=cv2.INTER_CUBIC)
 a+=rng.normal(0,1.1,(n,n));return a
def put(p,a):
 ok,b=cv2.imencode('.png',a);assert ok;p.parent.mkdir(parents=True,exist_ok=True);b.tofile(str(p));return sha(p)
def generate():
 manifest=[];truth=[];folder=O/'04_candidate_evidence/DEV_inputs';assert not folder.exists(),'New DEV run required'
 for bg in range(2):
  for rep,n in enumerate([512,704]):
   for family in FAMILIES:
    shared='pair'if family in ['false_tail','true_long']else family
    seed=202611050000+bg*10000+rep*100+FAMILIES.index('false_tail'if shared=='pair'else family)
    rng=np.random.default_rng(seed);a=baseimage(rng,n,bg);o=np.array([.19*n,.45*n]);d=.32*n;rp=np.array([o+[0,-d/2],o+[0,d/2]]);rad=.044*n;root=o+[rad,0];cv2.circle(a,tuple(o.astype(int)),round(rad),4,-1)
    t=np.linspace(0,1,500);p=root+np.column_stack([.27*n*t,.004*n*np.sin(2*np.pi*t)])
    if family.startswith('cross'):
     if family=='crossS':p[:,1]+=.045*n*np.sin(2*np.pi*t)
     else:
      angle=np.deg2rad(55 if family=='cross55'else 75);theta=angle*np.clip((t-.20)/.80,0,1);p=root+np.cumsum(np.column_stack([np.cos(theta),np.sin(theta)])*.27*n/(len(t)-1),axis=0);p-=p[0]-root
     q=p[260];fiber=q+np.column_stack([.12*n*(t-.5),-.25*n*(t-.5)]);a=paint(a,fiber,45,2)
    tail=p[-1]+np.column_stack([.28*n*t,.018*n*np.sin(np.pi*t)]);long=np.vstack([p,tail[1:]]);ref=a.copy();cur=a.copy();positive=family not in ['negative','static_negative','hole_motion'];observable=positive and family!='closure';w=1.8 if n==512 else 2.3
    if shared=='pair':
     cur=paint(paint(a,p,60,w),tail,60,w*2)
     if family=='false_tail':ref=paint(a,tail,14,w*2)
     else:p=long
    elif family=='static_negative':ref=paint(a,p,58,w);cur=ref.copy()
    elif family=='early':p=root+np.column_stack([.04*n*t,np.zeros(len(t))]);cur=paint(a,p,17,w)
    elif family=='weak':cur=paint(a,p,15,w)
    elif family=='preexisting':ref=paint(a,p[:230],45,w);cur=paint(a,p,55,w)
    elif family in ['negative','hole_motion','closure']:cur=a.copy()
    else:cur=paint(a,p,55,w)
    if family=='low_texture':
     ref=cv2.GaussianBlur(ref,(0,0),6);clean=cv2.GaussianBlur(a,(0,0),6);cur=paint(clean,p,55,w)
    if family=='repeated':
     yy,xx=np.mgrid[:n,:n];repeat=5*np.sin(xx*2*np.pi/6)+4*np.cos(yy*2*np.pi/7);ref+=repeat;cur+=repeat
    name=f'DEV_{bg}_{n}_{family}';refpath=folder/name/'ref.png';refsha=put(refpath,np.clip(np.rint(ref),0,255).astype('uint8'))
    for frame in [1,2,3]:
     angle=.002*(frame-2);R=np.array([[np.cos(angle),-np.sin(angle)],[np.sin(angle),np.cos(angle)]]);tr=np.array([.65*frame,-.4*frame]);M=np.column_stack([R,tr]);curframe=cur.copy();path=p.copy()
     if family=='gain_offset':curframe=.88*curframe+19
     if family=='reflection':
      yy,xx=np.mgrid[:n,:n];curframe+=70*np.exp(-((xx-.49*n)/(.08*n))**2-((yy-.46*n)/(.18*n))**2)
     if family=='nonrigid':
      yy,xx=np.mgrid[:n,:n];dx=3*np.sin(yy*10/n);curframe=cv2.remap(curframe.astype('float32'),(xx+dx).astype('float32'),yy.astype('float32'),cv2.INTER_LINEAR);path[:,0]-=3*np.sin(path[:,1]*10/n)
     if family=='hole_motion':
      curframe=cv2.warpAffine(curframe,np.float32([[1,0,3],[0,1,-2]]),(n,n),borderValue=210)
     current=cv2.warpAffine(curframe.astype('float32'),M,(n,n),borderValue=210);cp=apply(M,rp);path=apply(M,path)
     if family=='anchor_error':cp+=np.array([4.5,-2.5])
     # Pair RNG state is identical: same current pixels, anchors and histories.
     current=np.clip(np.rint(current+rng.normal(0,.6,current.shape)),0,255).astype('uint8');dtype='GRAY8'
     if family=='gain_offset'and rep==1:current=current.astype('uint16')*257;dtype='GRAY16'
     file=folder/name/f'{frame}.png';sh=put(file,current)
     manifest.append(dict(case_id=name,frame_id=frame,family=family,background='FOURIER_PHASE_SURFACE'if bg==0 else'REACTION_DIFFUSION',cluster_id=f'DEV_PAIR_{bg}_{n}'if shared=='pair'else name,pair_id=f'DEV_PAIR_{bg}_{n}'if shared=='pair'else None,reference_image=str(refpath),input_image=str(file),input_sha256=sh,ref_sha256=refsha,reference_points=rp.tolist(),points=cp.tolist(),pixel_encoding=dtype,role='ENGINEERING_DEV_NO_TEST_CLAIM',seed=seed))
     truth.append(dict(case_id=name,frame_id=frame,positive=positive,observable=observable,tip=path[-1].tolist()if observable else None,path=path.tolist()if observable else[],definition='rendered geometric visible centerline endpoint, finite-contrast procedural GT; not physical GT'))
 csvout(O/'04_candidate_evidence/DEV_manifest.csv',manifest);write(O/'04_candidate_evidence/DEV_GT.jsonl','\n'.join(json.dumps(t)for t in truth)+'\n');save(O/'04_candidate_evidence/DEV_input_seal.json',dict(utc=utc(),files={str(p):sha(p)for p in folder.rglob('*.png')},manifest_sha=sha(O/'04_candidate_evidence/DEV_manifest.csv'),GT_sha=sha(O/'04_candidate_evidence/DEV_GT.jsonl')))
 return manifest,truth

def execute(mm,gt):
 pred=[];candidates=[];segs=[];records=[];counter=[];pairs={};truth={(x['case_id'],x['frame_id']):x for x in gt};gate=json.loads((O/'03_reference_validity/gate1_decision.json').read_text(encoding='utf8'))
 with (O/'04_candidate_evidence/DEV_predictions.jsonl').open('w',encoding='utf8')as fo:
  for case in dict.fromkeys(r['case_id']for r in mm):
   rr=[r for r in mm if r['case_id']==case];ref=read(rr[0]['reference_image']);rp=rr[0]['reference_points'];cache=ReferenceCache(ref,rp);engine=api.Baseline(ref,rp,mode='auto');engine.run(ref,rp,True)
   for m in rr:
    raw=read(m['input_image']);a=engine.run(raw,m['points']);f=a['formal'];path=f['raw_path'];M=np.array(a['native']['transform_reference_to_current']);co,u,d=anchors(m['points']);target=path if len(path)else[co];reg=cache.match(raw,M,target);photo=cache.photo(raw,reg);ev,ms=path_evidence(ref,raw,path,reg,photo,f['width_px']or 2);t=truth[case,m['frame_id']]
    error=float(np.linalg.norm(np.array(f['tip'])-t['tip']))if f['confirmed_tip']and t['observable']else None
    row=dict(case_id=case,frame_id=m['frame_id'],family=m['family'],background=m['background'],cluster_id=m['cluster_id'],input_sha256=m['input_sha256'],A_tip_valid=f['confirmed_tip'],A_tip=f['tip'],Aprime_tip_valid=f['confirmed_tip'],Aprime_tip=f['tip'],candidate_origin='EXACT_NATIVE_A'if f['confirmed_tip']else'NONE',candidate_count=int(f['confirmed_tip']),alignment=reg['state'],photometry=photo['state'],local_joint=reg['local_supported']and photo['state']=='PHOTO_SUPPORTED',decision='KEEP_A_RESEARCH_FALLBACK',GT_positive=t['positive'],GT_observable=t['observable'],A_error_px=error,Aprime_error_px=error,A_correct=bool(error is not None and error<=8),A_prime_correct=bool(error is not None and error<=8),A_ms=f['api_ms'],Aprime_native_ms='NOT_TESTED',A_prime_loss=min(error,64)if error is not None else 32 if t['observable']else None)
    pred.append(row);z=dict(**row,input_image=m['input_image'],reference_image=m['reference_image'],points=m['points'],A=a,reg=reg,photo=photo,path_evidence=ev,GT=t);fo.write(json.dumps(z,default=scalar,allow_nan=False)+'\n')
    if f['confirmed_tip']:candidates.append(dict(case_id=case,frame_id=m['frame_id'],candidate_id=0,origin='EXACT_NATIVE_A',x=f['tip'][0],y=f['tip'][1],bitwise_preserved=True,reference_alignment=reg['state'],photometry=photo['state'],ownership='INSUFFICIENT_EVIDENCE',selected_as='LEGACY_FALLBACK_NOT_NEW_CONFIRMATION'))
    for e in ev:segs.append(dict(case_id=case,frame_id=m['frame_id'],**e))
    # Fixed-candidate numerical counterfactual: search ROI is deliberately not an input.
    ev2,_=path_evidence(ref,raw,path,reg,photo,f['width_px']or 2);counter.append(dict(case_id=case,frame_id=m['frame_id'],control='SEARCH_ROI_1.5_FIXED_CANDIDATE',identical_evidence=ev==ev2,new_search_executed=False))
    if m['pair_id']:
     # Probe determined solely by current anchors, not GT/A/reference-derived path.
     probe=co+np.arange(int(.06*d),int(2*d))[:,None]*u;rrg=dict(M=rigid(rp,m['points']),polygon=[],local_supported=False);php=dict(a=1.,b=0.,noise=1.,state='PHOTO_UNKNOWN');vv,_=path_evidence(ref,raw,probe,rrg,php,2.)
     pairs.setdefault((m['pair_id'],m['frame_id']),[]).append(dict(family=m['family'],image_sha=m['input_sha256'],cp=m['points'],Vcur=[e['Vcur']for e in vv],Vref=[e['Vref']for e in vv],DeltaV=[e['DeltaV']for e in vv],A_correct=row['A_correct'],A_error=error))
   engine.close();print('ENGINEERING_DEV',case,flush=True)
 csvout(O/'04_candidate_evidence/DEV_per_frame.csv',pred);csvout(O/'04_candidate_evidence/DEV_all_candidates.csv',candidates,fields=list(candidates[0])if candidates else['case_id','frame_id','candidate_id']);csvout(O/'04_candidate_evidence/DEV_path_segment_evidence.csv',segs);csvout(O/'04_candidate_evidence/ablation_and_counterfactual.csv',counter)
 pc=[]
 for (pid,fid),q in pairs.items():
  a,b=q;assert a['image_sha']==b['image_sha']and a['cp']==b['cp'];assert a['Vcur']==b['Vcur']
  pc.append(dict(pair_id=pid,frame_id=fid,same_current_and_anchors=True,CURRENT_ONLY_identical=True,reference_signal_differs=a['Vref']!=b['Vref'],raw_delta_signal_differs=a['DeltaV']!=b['DeltaV'],A_false_tail_error=next(x['A_error']for x in q if x['family']=='false_tail'),A_true_long_correct=next(x['A_correct']for x in q if x['family']=='true_long'),both_A_correct=all(x['A_correct']for x in q),causal_scope='fixed anchor-defined probe, NOT a detector endpoint prediction'))
 csvout(O/'04_candidate_evidence/matched_pair_and_crossing_controls.csv',pc)
 save(O/'04_candidate_evidence/DEV_engineering_summary.json',dict(frames=len(pred),cases=len(set(x['case_id']for x in pred)),A_correct=sum(x['A_correct']for x in pred),Aprime_correct=sum(x['A_prime_correct']for x in pred),A_correct_changed_wrong=0,A_correct_revoked=0,endpoint_replacement_enabled=False,real_gate1_passed=gate['pass_gate1'],strong_false_tail_activated=sum((x['A_false_tail_error']or 0)>32 for x in pc),paired_frames=len(pc),source='engineering only, no confirmatory TEST',utc=utc()))
if __name__=='__main__':
 guard();mm,gt=generate();execute(mm,gt);guard()
